SELECT r."title", r."content", r."duration", r."lesson_id", r."module_id", r."created_at", r."updated_at", r."description", r."order_index"
FROM jsonb_populate_recordset(NULL::public."lessons", '[{"title":"S35 - Create a coordinator account","content":"WHAT: We are creating a privileged account without storing a plaintext password.\nDO: Create a coordinator user with a per-user salt and scrypt password hash; inspect the account role using the safe Node/SQLite command.\nRUN / RESULT / CHECK: Coordinator role exists; stored password is hashed, not plaintext.\nIF IT FAILS: Use the documented PowerShell environment setup and account inspection; never record credentials in the workbook.\nSOURCE: Linked Module 06 PowerPoint, task S35 (original V25 teaching content).\nEVIDENCE: Grama_Learner_Evidence.xlsx > S01_S43_EXECUTION, row S35.","duration":"60","lesson_id":"50d0f3eb-ed57-42b3-a000-e42b34e9a2b0","module_id":"700759e6-a8d5-4d9f-9c79-6e724f3c101a","created_at":"2026-11-06T08:48:53.705644+00:00","updated_at":"2026-11-06T08:48:53.705644+00:00","description":null,"order_index":1},{"title":"Complete the document verification worksheet","content":"WORKPLACE: Aarohan Auto Components - fictional employee onboarding simulation. MODULE FILES: Record answers in the linked learner workbook. Use the same module source and guided deck from Drive.\nDO: Update 03_Document_Check with summary status, exact gap, next action and evidence note for each candidate.\n CHECK: Verify candidate ID, evidence, status and responsible owner. Do not mark pending items complete.","duration":"65","lesson_id":"512ed204-527f-4e9f-95f2-d59d017ac747","module_id":"a698052a-6425-4f3f-abc5-71ed1fc1f9cf","created_at":"2026-11-06T08:51:00.428159+00:00","updated_at":"2026-11-06T08:51:00.428159+00:00","description":null,"order_index":3},{"title":"Preserve Rohit’s joiner evidence before revocation","content":"WHAT WE ARE DOING: Complete IAM-J-201 while Rohit is still ENABLED. This historical joiner proof must be retained for the later leaver process.\nPRECONDITION: Log in with Rohit in a private browser using the ticket-specific portal URL http://127.0.0.1:5000/?ticket=IAM-J-201. Actually observe View 200 and Edit 403.\nRUN:\n.\\.venv\\Scripts\\python.exe capture_evidence.py IAM-J-201\nEXPECTED RESULT: EVIDENCE STATUS: PASS_AUTOMATED.\nCHECK: Save evidence/IAM-J-201.json with its transaction information. Do not recapture or overwrite this file after disabling Rohit.\nUNDERSTAND: Joiner proof describes access at provisioning time; leaver proof must later describe a separate removal event.\n\nSOURCE: Approved IAM L1 v8, source slide(s) 66. Module 05 (Empower).","duration":"20","lesson_id":"51b8a78a-b282-4975-9e54-da65828c72ac","module_id":"6d083266-9280-4761-a335-079183e1eb66","created_at":"2026-11-06T08:49:11.94133+00:00","updated_at":"2026-11-06T08:49:11.94133+00:00","description":null,"order_index":7},{"title":"Department Foundations - Guided Learning and Practice","content":"Work through Tasks 10-13 with the module learning deck and operating workbook.","duration":null,"lesson_id":"51d18202-266f-4fe7-9beb-47ebb0bb080a","module_id":"4aa839b4-1bca-4d40-91c5-58c7914b2145","created_at":"2026-11-06T08:37:35.754525+00:00","updated_at":"2026-11-06T08:37:35.754525+00:00","description":null,"order_index":1},{"title":"Basic Data Types","content":"Python has several built-in data types...","duration":"45 minutes","lesson_id":"527a266f-26ae-490f-af39-ce01291879f9","module_id":"fc939d58-cacf-46e7-a667-be22a419131e","created_at":"2026-11-04T06:07:51.940601+00:00","updated_at":"2026-11-04T06:07:51.940601+00:00","description":null,"order_index":1},{"title":"Inspect the customer score rules","content":"WORKPLACE: SwaadFit Foods and GrainGlow Foods - fictional packaged snacks marketing cases. MODULE FILES: Read the file linked in this lesson. Keep the original source file unchanged.\nDO: Read SwaadFit_M2_Source.xlsx including response percentages, 02_Score_Rule, product facts and later CrunchCo event.\n CHECK: Save the working record; open 90_Check_After_Attempt only after completing the task; do not invent approval, actual spending, conversion events or causal claims.","duration":"30","lesson_id":"52dd5318-6fbb-499e-9f3b-77df6b389287","module_id":"82d21194-c6d2-4f91-8a31-17f8e16bde2d","created_at":"2026-11-06T08:50:37.200527+00:00","updated_at":"2026-11-06T08:50:37.200527+00:00","description":null,"order_index":2},{"title":"Enter the HR operations workplace","content":"WORKPLACE: Aarohan Auto Components - fictional employee onboarding simulation. MODULE FILES: Open the linked guided deck and use the module source and learner workbook from the same Drive course folder. COURSE SOURCE FOLDER: https://drive.google.com/drive/folders/1aIg_7JAB3MUm7YG0bpDWRYDMGqqivPex.\nDO: Open the module deck and identify the HR coordinator role, fictional Plant A case and purpose of a controlled recruitment handover.\n CHECK: Verify candidate ID, evidence, status and responsible owner. Do not mark pending items complete.","duration":"20","lesson_id":"52e70560-6e33-4145-a46a-5e7f885224c2","module_id":"fdb51063-72ec-4a25-a5fe-514c4c631648","created_at":"2026-11-06T08:50:56.728261+00:00","updated_at":"2026-11-06T08:50:56.728261+00:00","description":null,"order_index":1},{"title":"Fluid Mechanics and River Hydraulics","content":"Calculate river discharge from area and velocity. Explore the effect of a smaller pipe on flow speed, and learn how pressure, head and pump efficiency relate. Use Reynolds number to distinguish flow conditions. Interpret each result with its assumptions.","duration":"30 minutes","lesson_id":"52f1a61a-b4d8-4849-85f8-478b38db8dbd","module_id":"34144afd-427e-4306-a792-d52fb063b79a","created_at":"2026-11-17T06:34:23.780472+00:00","updated_at":"2026-11-17T06:34:23.780472+00:00","description":null,"order_index":1},{"title":"Video Resume — How to Create and Submit","content":"PARTICIPANT INTRODUCTION: Video Resume\nShow who you are, what you can do and what you hope to achieve.\n\nHOW TO CREATE YOUR VIDEO RESUME\n1. Plan — Prepare a short introduction covering your education, skills and one real example.\n2. Record — Face the camera, use a quiet well-lit space and speak clearly in your own words.\n3. Review — Watch the recording; check your voice, picture and accuracy before finalising.\n4. Submit — Follow the stated duration and format, then upload through the shared channel.\n\nSESSION FOCUS: Introduce yourself with confidence and evidence, not memorised claims.\n\nRESOURCE: See the attached Video Resume introductory presentation.","duration":null,"lesson_id":"5304e609-c058-4dda-83a8-29358c0dff9b","module_id":"7e26c5cc-73fe-45a8-aa42-58f2e54e4cbc","created_at":"2026-11-06T08:45:31.047285+00:00","updated_at":"2026-11-06T08:45:31.047285+00:00","description":null,"order_index":1},{"title":"Inspect each candidate document record","content":"WORKPLACE: Aarohan Auto Components - fictional employee onboarding simulation. MODULE FILES: Read the file linked in this lesson. Keep the original source file unchanged.\nDO: Read the module Source Data and link document evidence, identity and candidate ID before deciding status.\n CHECK: Verify candidate ID, evidence, status and responsible owner. Do not mark pending items complete.","duration":"35","lesson_id":"53c201bb-0e32-4c5b-9e65-c53dc5c3d801","module_id":"a698052a-6425-4f3f-abc5-71ed1fc1f9cf","created_at":"2026-11-06T08:50:59.857869+00:00","updated_at":"2026-11-06T08:50:59.857869+00:00","description":null,"order_index":2},{"title":"Create role-based setup request records","content":"WORKPLACE: Aarohan Auto Components - fictional employee onboarding simulation. MODULE FILES: Record answers in the linked learner workbook. Use the same module source and guided deck from Drive.\nDO: Complete 04_Setup_Requests with required setup, request recipient, request date and day-one criticality.\n CHECK: Verify candidate ID, evidence, status and responsible owner. Do not mark pending items complete.","duration":"55","lesson_id":"53fbc172-f4d0-4db9-9c13-1bbaa254c681","module_id":"067167c1-86b5-4777-b5a0-a4df453dd68c","created_at":"2026-11-06T08:51:02.98536+00:00","updated_at":"2026-11-06T08:51:02.98536+00:00","description":null,"order_index":3},{"title":"T01 - Count paid teams","content":"Work task T01: Count paid teams.\nPRACTICE FILE - INTERACTIVE SIMULATOR: Use the linked resource in this lesson. Download the HTML file from Google Drive, then open it in Chrome or Edge; the Drive preview does not run the simulator. Keep the same file and browser for all modules.\nOpen: Team bookings in the shared offline simulator.\n1. Open Team bookings.\n2. Set Payment to captured and Status to confirmed.\n3. Type the number of paid teams in the check box.\nCompleted example: Payment filter: captured; Team status: confirmed; Result: 5 paid teams.\nCheck in simulator: 5 paid teams.\nWhy: A team takes one place only after payment is successful and its booking is confirmed.\nFirst-time setup: download the HTML simulator from its Drive link; open the file in Chrome or Edge. Open the module PowerPoint beside it. Keep the same simulator and browser across all modules.\nSimulator file: https://drive.google.com/file/d/1gI5LWjKJZAE-__OzQo1vqFr1s6oHmOgu/view?usp=drivesdk\nMODULE SLIDES (PowerPoint): https://docs.google.com/presentation/d/1qf78k8RvV7GgG3Rm725jIXzCtZ4LDmes/edit?usp=drivesdk&ouid=117748485795287437293&rtpof=true&sd=true","duration":"15","lesson_id":"5425049a-7580-4d87-9c4f-fc6316595955","module_id":"681f39c1-fc77-4026-b85b-29f1521668ef","created_at":"2026-11-06T08:49:17.343318+00:00","updated_at":"2026-11-06T08:49:17.343318+00:00","description":null,"order_index":1},{"title":"S29 - Display server connection state","content":"WHAT: We are showing whether the Grama page has connected to the live server.\nDO: Add a visible server-connection indicator to the client HTML and supporting JavaScript.\nRUN / RESULT / CHECK: The UI reports whether its Express backend can be reached.\nIF IT FAILS: Check the server is still running and browser Console has no fetch error.\nSOURCE: Linked Module 05 PowerPoint, task S29 (original V25 teaching content).\nEVIDENCE: Grama_Learner_Evidence.xlsx > S01_S43_EXECUTION, row S29.","duration":"45","lesson_id":"543f2e23-8988-4109-91da-7a376b4dabb2","module_id":"cb186bda-f107-4d57-bf65-07aa218b21ef","created_at":"2026-11-06T08:48:49.997949+00:00","updated_at":"2026-11-06T08:48:49.997949+00:00","description":null,"order_index":4},{"title":"Explain: Finance Analytics","content":"MODULE 1: Finance Analytics\n6E STAGE: Explain\nSOURCE SLIDE CONTENT:\nFINANCE — ANSWER CHECK\nSouth\nSouth shows lower revenue, lower margin and higher CCC in Jul–Sep.\n\nRESOURCE: M1_Finance_Explain.pptx","duration":null,"lesson_id":"54aaa171-b780-451f-b32d-0812504b6a88","module_id":"a4e8da2a-aba5-4f08-b27c-c417f244968c","created_at":"2026-11-06T08:40:16.718627+00:00","updated_at":"2026-11-06T08:40:16.718627+00:00","description":null,"order_index":3},{"title":"Water Quality Parameters and Their Relationships","content":"Identify temperature, turbidity and suspended solids and their measurement units. Compare pH, conductivity and dissolved salts. Learn how DO, BOD and COD differ, including a five-day BOD calculation and its quality checks. Understand microbial indicator results and their limits.","duration":"30 minutes","lesson_id":"54b1552c-04ce-47d4-8339-df3039bae93c","module_id":"024c30e5-6571-4546-baa5-6faeead3271d","created_at":"2026-11-17T06:34:31.953933+00:00","updated_at":"2026-11-17T06:34:31.953933+00:00","description":null,"order_index":1},{"title":"Grade 11 Economics — Scarcity, Incentives and Water Allocation","content":"Complete Grade 11 Economics course presentation. Open the linked PowerPoint in resource_url for the full teaching content, examples and activities.","duration":null,"lesson_id":"55fbf1b4-b9bf-4c62-882b-62f2602a8394","module_id":"8b4dc608-a916-42d9-88a5-434efc01968b","created_at":"2026-11-16T09:14:43.918443+00:00","updated_at":"2026-11-16T09:14:43.918443+00:00","description":null,"order_index":1},{"title":"T27 - Set ₹3,000 lifetime budget in the Ad set","content":"Work task T27: Set ₹3,000 lifetime budget in the Ad set.\nPRACTICE FILE - INTERACTIVE SIMULATOR: Use the linked resource in this lesson. Download the HTML file from Google Drive, then open it in Chrome or Edge; the Drive preview does not run the simulator. Keep the same file and browser for all modules.\nOpen: Ads Manager (practice) in the shared offline simulator.\n1. Open Ads Manager > Ad sets.\n2. Set Lifetime budget to ₹3,000.\n3. Save ad set settings; do not place this training budget in Campaign settings.\nCompleted example: Where: Ads Manager > Ad sets; Budget type: Lifetime; Amount: ₹3,000.\nCheck in simulator: ₹3,000.\nWhy: The budget location must match the approved training configuration.\nSimulator file: https://drive.google.com/file/d/1gI5LWjKJZAE-__OzQo1vqFr1s6oHmOgu/view?usp=drivesdk\nMODULE SLIDES (not yet uploaded to Drive): Module_05_Build_the_Ad_Campaign/M05_Build_the_Ad_Campaign.pptx\nLMS ADMIN ACTION: Upload this module deck separately before learner publication.","duration":"25","lesson_id":"5740b9a0-83c5-4575-87d5-838dc44d3024","module_id":"5e0d6e1b-e6fa-450d-93da-45fb48e4bcb7","created_at":"2026-11-06T08:49:33.246586+00:00","updated_at":"2026-11-06T08:49:33.246586+00:00","description":null,"order_index":3},{"title":"Complete Day 7, Day 30 and Day 60 follow-ups","content":"WORKPLACE: Aarohan Auto Components - fictional employee onboarding simulation. MODULE FILES: Record answers in the linked learner workbook. Use the same module source and guided deck from Drive.\nDO: Use 13_Transfer_Followups keyed by Candidate ID plus checkpoint and reconcile outcomes with the main transfer tracker.\n CHECK: Verify candidate ID, evidence, status and responsible owner. Do not mark pending items complete.","duration":"65","lesson_id":"57c477ad-03dc-4a56-aca4-766c2adb35f5","module_id":"1a9397ae-439a-4b11-a6a7-a53ccaa97535","created_at":"2026-11-06T08:51:21.722881+00:00","updated_at":"2026-11-06T08:51:21.722881+00:00","description":null,"order_index":5},{"title":"Verify action benefits and next owners","content":"WORKPLACE: Sri Lakshmi Foods - fictional finance workplace case. MODULE FILES: Record answers in the linked learner workbook. Use the same module source and guided deck from Drive.\nDO: Complete 06_BENEFITS with planned versus observed benefit, variance, status, action owner and follow-up; keep EBITDA and cash categories distinct.\n CHECK: Save the source-supported output and carry unresolved items to the next task; management approvals are not implied.","duration":"55","lesson_id":"57ffd35a-901c-4479-8b64-fab6aff17283","module_id":"056822e1-887b-4a10-99e9-70f234cd58b5","created_at":"2026-11-06T08:50:05.925788+00:00","updated_at":"2026-11-06T08:50:05.925788+00:00","description":null,"order_index":4},{"title":"Engage: Marketing and Sales Analytics","content":"MODULE 4: Marketing and Sales Analytics\n6E STAGE: Engage\nSOURCE SLIDE CONTENT:\nMARKETING & SALES\nMARKETING & SALES TASK\nWhere is acquisition efficiency or sales conversion weakening?\nUse these sheets\n12_Mkt_Campaign_Data\n13_Sales_Lead_Pipeline\n14_Rural_Market_Data\n15_Product_Master\nCalculate acquisition efficiency\nSpend, Leads, Conversions, Conversion Rate, ROAS and Cost per Conversion.\nExamine sales conversion\nSales Win Rate, Follow-Ups and Objections.\n\nRESOURCE: M4_Marketing_and_Sales_Engage.pptx","duration":null,"lesson_id":"587278d6-3f65-4ac6-b9b4-b1dec187b8a3","module_id":"42b2abe9-d25a-4686-8887-58a6810cdd28","created_at":"2026-11-06T08:40:25.902886+00:00","updated_at":"2026-11-06T08:40:25.902886+00:00","description":null,"order_index":1},{"title":"Empower: Finance Analytics","content":"MODULE 1: Finance Analytics\n6E STAGE: Empower\nSOURCE SLIDE CONTENT:\nBUILD THE FINANCE POWER BI DASHBOARD\nLoad Fin_Performance and Fin_Working_Capital.\nLink Month and Region dimensions.\nCreate measures and 5 KPI cards: Revenue, Rev Var %, Operating Profit, Operating Margin %, CCC.\nAdd Budget vs Actual, Margin by Region and CCC visuals.\nAdd Month and Region slicers.\n\nRESOURCE: M1_Finance_Empower.pptx","duration":null,"lesson_id":"5891c901-a51b-4cc4-8796-48036eed1a55","module_id":"a4e8da2a-aba5-4f08-b27c-c417f244968c","created_at":"2026-11-06T08:40:18.321552+00:00","updated_at":"2026-11-06T08:40:18.321552+00:00","description":null,"order_index":6},{"title":"Student Assessment — How to Complete Your Assessment","content":"PARTICIPANT INTRODUCTION: Student Assessment\nComplete the assessment carefully so your starting point is understood.\n\nHOW TO COMPLETE YOUR ASSESSMENT\n1. Read — Check the instructions, question types, time limits and submission rules.\n2. Respond — Answer independently; give honest responses to interest and preference questions.\n3. Review — Check your answers and any unanswered items before submitting, if permitted.\n4. Submit — Submit as instructed and confirm that your attempt has been recorded.\n\nSESSION FOCUS: Provide a reliable starting point for future guidance and development.\n\nRESOURCE: See the attached Student Assessment introductory presentation.","duration":null,"lesson_id":"58971479-dcb1-47c6-98b9-3a109c195724","module_id":"77cb2c00-4c73-4117-a42c-6a00d789a6b1","created_at":"2026-11-06T08:45:33.727011+00:00","updated_at":"2026-11-06T08:45:33.727011+00:00","description":null,"order_index":1},{"title":"Rivers, Watersheds and Hydrology","content":"Identify a watershed, drainage divide and tributaries. Follow rainfall through infiltration and runoff. Read a river hydrograph, calculate flow and peak lag, and explain how groundwater can enter or leave a river. Use the diagrams and worked examples to check understanding.","duration":"30 minutes","lesson_id":"58b54945-3259-44f4-b38e-f6fc5edf6e87","module_id":"6be4571e-3c1b-406b-b5a3-b258f72a0b5c","created_at":"2026-11-17T06:34:22.432944+00:00","updated_at":"2026-11-17T06:34:22.432944+00:00","description":null,"order_index":1},{"title":"Try Alone: Find the Rule for Coin 19","content":"In the simulator, study R, L, C, C, R, L, C, C. Identify the repeating group and predict coin 19 using structured mathematical reasoning. Hints and retries remain available, but assisted work is recorded separately.","duration":null,"lesson_id":"59f4c859-99f5-4ba1-a707-da551e55308a","module_id":"d4d7a7ff-2205-4fcc-bef4-f935f149d458","created_at":"2026-11-05T09:47:45.785001+00:00","updated_at":"2026-11-05T09:47:45.785001+00:00","description":null,"order_index":2},{"title":"Set Rohit’s local login credential","content":"WHAT WE ARE DOING: Enable the approved test identity to sign in and prove access.\nI SHOW — REFERENCE: Observe the paired reference action in the separate reference environment.\nREFERENCE ACTION / COMMAND:\n.\\.venv\\Scripts\\python.exe reference_show.py 17\n# REFERENCE realm only; do NOT run work.py yet.\nI TRY — EXACT REPEAT: Use the same code or clicks shown, unchanged, in your own learner lab. For Python tasks, put the complete code below into the learner work.py file. Do not repeat a state-changing account creation twice in the same realm.\nCODE / EXACT TOOL ACTION:\nfrom iam_api import connect, find_user, ROOT\ns = connect(\"IAM-J-201\")\nu = find_user(s, \"rohit.nair\")\nassert u, \"STOP: create user first\"\nr = s.put(f\"{ROOT}/users/{u[''id'']}/reset-password\",\n    json={\"type\": \"password\", \"value\": \"RohitLab!2026\",\n          \"temporary\": False}, timeout=15)\nr.raise_for_status()\nprint(\"PASSWORD: Rohit test credential saved\")\nRUN / PERFORM:\n.\\.venv\\Scripts\\python.exe work.py\nEXPECTED RESULT:\nPASSWORD: Rohit test credential saved\nCHECK AGAINST THE ACTUAL RESULT:\nPassword is only for the isolated training lab.\nDo not copy it into the evidence file.\nThe portal login must still be tested.\nUNDERSTAND:\nThe test credential lets you verify the account; it is not authorization.\n\nSOURCE: Approved IAM L1 v8, source slide(s) 60–61 (Guided task 17). Module 05 (Empower).","duration":"45","lesson_id":"5aeac91b-592f-40d3-bc26-bda6ffb86fbf","module_id":"6d083266-9280-4761-a335-079183e1eb66","created_at":"2026-11-06T08:49:11.088891+00:00","updated_at":"2026-11-06T08:49:11.088891+00:00","description":null,"order_index":4},{"title":"Watch the Coin Trail (optional presentation)","content":"The runner needs to find a missing coin. Watch the first nine coins and look for a repeating order. Pause before the coin 10 prediction. The slide deck is optional because the simulator contains the complete lesson.","duration":null,"lesson_id":"5bdc6a34-79b5-4ed6-82d7-77fd44ad3304","module_id":"1e5dd0b7-4d92-4c1b-9680-7b1d66d63911","created_at":"2026-11-05T09:47:42.099487+00:00","updated_at":"2026-11-05T09:47:42.099487+00:00","description":null,"order_index":1},{"title":"Start the reporting application","content":"WHAT WE ARE DOING: Start a separate application that will prove whether access is allowed.\nI SHOW — REFERENCE: Observe the paired reference action in the separate reference environment.\nREFERENCE ACTION / COMMAND:\nStart the reference portal; verify http://127.0.0.1:5001/health\nI TRY — EXACT REPEAT: Use the same code or clicks shown, unchanged, in your own learner lab. For Python tasks, put the complete code below into the learner work.py file. Do not repeat a state-changing account creation twice in the same realm.\nCODE / EXACT TOOL ACTION:\npy -m venv .venv\n.\\.venv\\Scripts\\python.exe -m pip install -r app\\requirements.txt\n.\\.venv\\Scripts\\python.exe app\\app.py\nRUN / PERFORM:\nPowerShell: run all lines. Leave this terminal open.\nEXPECTED RESULT:\nRunning on http://127.0.0.1:5000\n(After the packages install.)\nCHECK AGAINST THE ACTUAL RESULT:\nIn a NEW PowerShell tab, visit:\nhttp://127.0.0.1:5000/health\nJSON status must be app-running.\nUNDERSTAND:\nKeycloak stores access. The separate application proves the actual effect.\n\nSOURCE: Approved IAM L1 v8, source slide(s) 22–23 (Guided task 02). Module 02 (Explore).","duration":"60","lesson_id":"5c2dccfa-831c-4e47-b513-de86f4090fee","module_id":"11649aa6-8081-45b1-bd24-94c42727b4dd","created_at":"2026-11-06T08:49:04.230711+00:00","updated_at":"2026-11-06T08:49:04.230711+00:00","description":null,"order_index":2},{"title":"T46 - Calculate campaign performance","content":"Work task T46: Calculate campaign performance.\nPRACTICE FILE - INTERACTIVE SIMULATOR: Use the linked resource in this lesson. Download the HTML file from Google Drive, then open it in Chrome or Edge; the Drive preview does not run the simulator. Keep the same file and browser for all modules.\nOpen: Final report in the shared offline simulator.\n1. Open Final report > Calculate.\n2. Enter CTR, CPC, cost per paid team and ROAS.\n3. Press Verify calculations.\nCompleted example: CTR: 2.13%; CPC: ₹7.03; Cost/new paid team: ₹262.73; Gross ROAS: 2.85×.\nCheck in simulator: 2.85×.\nWhy: These numbers tell the manager what the ads achieved for the money.\nSimulator file: https://drive.google.com/file/d/1gI5LWjKJZAE-__OzQo1vqFr1s6oHmOgu/view?usp=drivesdk\nMODULE SLIDES (PowerPoint): https://docs.google.com/presentation/d/17IglBQnnnIL9v2w0psRL_Vp2qeuQIzWf/edit?usp=drivesdk&ouid=117748485795287437293&rtpof=true&sd=true","duration":"25","lesson_id":"5cacf8b3-b139-4a57-ac2e-a07cc0cd7923","module_id":"216fd3f2-3bed-47da-be6f-5611e637a457","created_at":"2026-11-06T08:49:44.896359+00:00","updated_at":"2026-11-06T08:49:44.896359+00:00","description":null,"order_index":3},{"title":"Presentations, Evaluations & Interview Screening: Session Introduction","content":"SESSION: Presentations & Evaluations — Interview Screening\nINTRODUCTION: Participant introduction session. Show how you think, communicate and respond—not only what you know. Session focus: Demonstrate your capabilities and understand the next stage.\n\nSESSION PARTICIPATION STEPS\n1. Check the brief: Confirm the format, preparation needs and any time limits provided.\n2. Present clearly: Introduce yourself and explain your work or ideas with relevant examples.\n3. Respond thoughtfully: Listen carefully, answer accurately and explain your reasoning.\n4. Close and reflect: Ask about the next stage and note feedback or follow-up actions.\n\nSESSION FOCUS: Demonstrate your capabilities and understand the next stage.\nRESOURCE: See linked presentation (Presentations_Evaluations_Interview_Screening_Introduction.pptx).","duration":"60","lesson_id":"5cd8f0f9-6325-4bb1-8622-32b7281d8762","module_id":"743294d4-80ff-48f7-ae6e-b20e1fad1d7b","created_at":"2026-11-06T08:43:01.482011+00:00","updated_at":"2026-11-06T08:43:01.482011+00:00","description":null,"order_index":1},{"title":"Create Ananya in Keycloak","content":"WHAT WE ARE DOING: Create the approved employee identity; do not assign permissions yet.\nI SHOW — REFERENCE: Observe the paired reference action in the separate reference environment.\nREFERENCE ACTION / COMMAND:\n.\\.venv\\Scripts\\python.exe reference_show.py 06\n# REFERENCE realm only; do NOT run work.py yet.\nI TRY — EXACT REPEAT: Use the same code or clicks shown, unchanged, in your own learner lab. For Python tasks, put the complete code below into the learner work.py file. Do not repeat a state-changing account creation twice in the same realm.\nCODE / EXACT TOOL ACTION:\nfrom iam_api import connect, find_user, ROOT\ns = connect(\"IAM-J-101\")\nassert find_user(s, \"ananya.shah\") is None, \"HOLD: duplicate\"\nrecord = {\n    \"username\": \"ananya.shah\", \"firstName\": \"Ananya\",\n    \"lastName\": \"Shah\", \"email\": \"ananya.shah@example.test\",\n    \"enabled\": True\n}\nr = s.post(f\"{ROOT}/users\", json=record, timeout=15)\nr.raise_for_status()\nu = find_user(s, \"ananya.shah\")\nprint(\"CREATED:\", u[\"username\"], \"| ENABLED:\", u[\"enabled\"])\nRUN / PERFORM:\n.\\.venv\\Scripts\\python.exe work.py\nEXPECTED RESULT:\nCREATED: ananya.shah | ENABLED: True\nCHECK AGAINST THE ACTUAL RESULT:\nFind ananya.shah in Keycloak Users.\nCheck name and email exactly.\nNo second or editor account should appear.\nUNDERSTAND:\nCreating an account gives the employee an identity, not report permission.\n\nSOURCE: Approved IAM L1 v8, source slide(s) 33–34 (Guided task 06). Module 03 (Explain).","duration":"60","lesson_id":"5e19873a-1cfb-4e61-ba49-627f165d6553","module_id":"fc3b345d-ea20-4ef5-8693-9796ed1939b5","created_at":"2026-11-06T08:49:06.262547+00:00","updated_at":"2026-11-06T08:49:06.262547+00:00","description":null,"order_index":3},{"title":"Test new patterns and save your results","content":"Open the standalone Module 02 HTML offline. Check the scoreboards, use all intermediate differences to prove each classification, practise first term and common difference, revise mistakes and save the learner evidence record.","duration":null,"lesson_id":"5e1c1e91-1ca8-4a6a-bedd-a41208937856","module_id":"307d06a3-fea2-4ab1-8c05-797ce3df083c","created_at":"2026-11-05T09:47:55.099243+00:00","updated_at":"2026-11-05T09:47:55.099243+00:00","description":null,"order_index":3},{"title":"Understand the October closing assignment","content":"WORKPLACE: Sri Lakshmi Foods - fictional finance workplace case. MODULE FILES: Open the linked guided deck and use the module source and learner workbook from the same Drive course folder.\nDO: Read why a month can be below revenue forecast yet ahead of EBITDA expectations due to cost differences.\n CHECK: Save the source-supported output and carry unresolved items to the next task; management approvals are not implied.","duration":"20","lesson_id":"5e45736f-eb57-4334-b311-cf37bcc273b8","module_id":"056822e1-887b-4a10-99e9-70f234cd58b5","created_at":"2026-11-06T08:50:04.222087+00:00","updated_at":"2026-11-06T08:50:04.222087+00:00","description":null,"order_index":1},{"title":"S05 - Create a search field","content":"WHAT: We are adding an input where visitors can type a resource name.\nDO: Create and style the labelled search input in index.html and styles.css. Do not add filtering behavior yet.\nRUN / RESULT / CHECK: The input accepts text but typing wifi does NOT hide the existing resource card.\nIF IT FAILS: If the card disappears, check that JavaScript filtering has not been added early.\nSOURCE: Linked Module 02 PowerPoint, task S05 (original V25 teaching content).\nEVIDENCE: Grama_Learner_Evidence.xlsx > S01_S43_EXECUTION, row S05.","duration":"35","lesson_id":"60258621-e447-45da-a0d9-93fcd11cae2b","module_id":"7a584fec-8468-485f-aad3-a5fe02e103ca","created_at":"2026-11-06T08:48:35.501359+00:00","updated_at":"2026-11-06T08:48:35.501359+00:00","description":null,"order_index":1}]'::jsonb) r
WHERE r.module_id IN (SELECT module_id FROM public.course_modules WHERE course_id IN (SELECT id FROM lms_demo_missing_courses))
ON CONFLICT DO NOTHING;

